{{родств-блок
|имена-собственные=
|существительные=призыв, призвание, призывник, призывание, призыватель
|прилагательные=призывной, призванный
|глаголы=призываться, зывать; призвать, звать, вызвать, зазывать
|наречия=призывно
}}

